<script lang="ts">
  let { alerts = [], loading = false, error = '', onRefresh, onDetail, formatDate, duration, confidence, labelClass, statusLabel } = $props<any>();
</script>

<section class="alerts-view surface">
  <div class="section-title"><div><h2>Eventos confirmados</h2><p>Inicio, fin, duración y evidencia asociada de cada alerta.</p></div><div class="section-actions"><span class="pill neutral">{alerts.length} eventos</span><button class="btn secondary" onclick={onRefresh} disabled={loading}>{loading ? 'Actualizando…' : '↻ Actualizar'}</button></div></div>
  {#if error}<div class="banner error"><strong>No se pudieron actualizar los eventos</strong><span>{error}</span></div>{/if}
  {#if alerts.length}<div class="event-list">{#each alerts as alert, i (alert.id ?? `${alert.fecha_hora}-${i}`)}<article class="event-card"><span class="event-symbol" aria-hidden="true">!</span><div class="event-body"><div class="event-heading"><strong>{labelClass(alert.clase)}</strong><span class:interrupted={alert.status === 'interrupted'} class="pill">{statusLabel(alert.status)}</span></div><dl class="event-metadata"><div><dt>Cámara</dt><dd>{alert.camera ?? '—'}</dd></div><div><dt>Inicio</dt><dd>{formatDate(alert.timestamp_inicio ?? alert.fecha_hora)}</dd></div><div><dt>Fin</dt><dd>{formatDate(alert.timestamp_fin ?? alert.fecha_hora_fin)}</dd></div><div><dt>Duración</dt><dd>{duration(alert.duracion_segundos)}</dd></div><div><dt>Confianza</dt><dd>{confidence(alert.confianza)}</dd></div><div><dt>Umbral</dt><dd>{confidence(alert.threshold)}</dd></div></dl>{#if alert.status === 'interrupted' && alert.interruption_reason}<p class="interruption"><strong>Motivo de interrupción:</strong> {alert.interruption_reason}</p>{/if}</div><button class="btn secondary" onclick={() => onDetail(alert)}>Ver detalle</button></article>{/each}</div>
  {:else}<div class="empty"><span class="placeholder-icon">◇</span><h3>{loading ? 'Consultando eventos…' : 'No hay alertas confirmadas'}</h3><p>{loading ? 'Esperando la respuesta del servidor de inferencia.' : 'Cuando el sistema confirme un evento, aparecerá aquí.'}</p></div>{/if}
</section>

<style>
  .alerts-view{padding:25px}.section-title,.section-actions,.event-heading{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.section-actions{align-items:center}.section-title h2{margin:0;font-size:16px}.section-title p,.event-card p{font-size:12px;color:#4a6178}.pill{display:inline-flex;padding:6px 9px;border-radius:5px;background:#fff4e8;color:#ac6a22;font-size:11px;font-weight:700}.pill.neutral{background:#eff3f8;color:#38546f}.pill.interrupted{background:#fdebec;color:#a3494d}.btn{border-radius:7px;padding:10px 15px;border:1px solid #d3deea;background:#fff;color:#2c4a6a;font-weight:650;font-size:12px}.event-list{display:flex;flex-direction:column}.event-card{display:flex;gap:15px;align-items:flex-start;padding:17px 0;border-bottom:1px solid #ecf1f6}.event-symbol{background:#fff0eb;color:#b85a43;font-weight:800;width:36px;height:36px;display:grid;place-items:center;border-radius:7px;flex:0 0 auto}.event-body{flex:1}.event-heading strong{color:#2e4862;text-transform:capitalize}.event-metadata{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:13px 0 0}.event-metadata dt{font-size:10px;font-weight:700;color:#71879d;text-transform:uppercase}.event-metadata dd{margin:4px 0 0;font-size:12px;color:#25405d}.interruption{background:#fff6ec;border-left:3px solid #d68736;padding:8px 10px;border-radius:3px}.empty{text-align:center;padding:55px 20px;color:#4a6178}.empty h3{color:#2c4966}.placeholder-icon{font-size:32px;display:block}.banner{display:flex;gap:12px;padding:13px 16px;margin:18px 0;border:1px solid #eed9ce;border-radius:7px;background:#fff7f2;color:#8c5038;font-size:12px}@media(max-width:600px){.event-metadata{grid-template-columns:repeat(2,minmax(0,1fr))}.event-card{flex-wrap:wrap}.event-card>.btn{margin-left:51px}}
</style>
